import { Container, Row, Col } from "react-bootstrap";
import { MailchimpForm } from "./MailchimpForm";
import navIcon1 from "../assets/img/nav-icon1.svg";
import navIcon2 from "../assets/img/nav-icon2.svg";
import navIcon3 from "../assets/img/nav-icon3.svg";

export const Footer = () => {
  return (
    <footer className="footer py-5">
      <Container>
        <Row className="align-items-center text-center text-md-start">

          {/* Newsletter Section */}
          <Col xs={12} md={6} className="mb-4 mb-md-0">
            <MailchimpForm />
          </Col>

          {/* Social Links Section */}
          <Col xs={12} md={6} className="text-center text-md-end">

            <div className="social-icon d-flex justify-content-center justify-content-md-end gap-3 mb-3">

              {/* LinkedIn */}
              <a
                href="https://www.linkedin.com/in/akashkalatippi"
                target="_blank"
                rel="noopener noreferrer"
              >
                <img src={navIcon1} alt="LinkedIn" width="30" />
              </a>

              {/* GitHub */}
              <a
                href="https://github.com/AkashKalatippi"
                target="_blank"
                rel="noopener noreferrer"
              >
                <img src={navIcon2} alt="GitHub" width="30" />
              </a>

              {/* Instagram */}
              <a
                href="https://www.instagram.com/akash_kalatippi"
                target="_blank"
                rel="noopener noreferrer"
              >
                <img src={navIcon3} alt="Instagram" width="30" />
              </a>

            </div>

            <p className="mb-0">
              © {new Date().getFullYear()} Akash Kalatippi. All Rights Reserved
            </p>

          </Col>
        </Row>
      </Container>
    </footer>
  );
};
